let firebaseContextReady=false;
async function ensureFirebaseRestaurant(staffToken){if(!staff||!staffToken||firebaseContextReady)return;firebaseContextReady=true;try{const response=await fetch('/api/account/profile',{headers:{Authorization:'Bearer '+staffToken}});if(!response.ok)return;const profile=await response.json(),memberships=profile.memberships||[],saved=localStorage.getItem('resuto-restaurant-id');if(memberships.length&&!memberships.some(row=>row.restaurantId===saved))localStorage.setItem('resuto-restaurant-id',memberships[0].restaurantId)}catch{}}
async function api(url,body){if(typeof authReady!=='undefined')await authReady;const staffToken=staff&&typeof firebaseIdToken==='function'?await firebaseIdToken():null;await ensureFirebaseRestaurant(staffToken);const restaurantId=staff&&typeof localStorage!=='undefined'?localStorage.getItem('resuto-restaurant-id'):null;const r=await fetch('/api/'+url,{method:body?'POST':'GET',headers:{'Content-Type':'application/json',...(staff?(staffToken?{Authorization:'Bearer '+staffToken,'X-Workspace-Role':role,...(restaurantId?{'X-Restaurant-ID':restaurantId}:{})}:{}):token?{Authorization:'Bearer '+token}:{})},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Object.assign(new Error(d.error),{status:r.status});return d}
