function close(){editing=false;$('dialog')?.close();$('dialog')?.remove()}
// Live table state, derived from the visit's real orders, requests and bill so
// the floor plan tracks service instead of only "somebody is sitting here".
function tableState(t){
 const v=data.visits?.find(v=>v.tableId===t.id&&v.status==='open');
 if(!v){
  if(t.cleaning)return {state:'cleaning',text:tr('Needs cleaning','تحتاج تنظيف')};
  const soon=data.reservations?.find(r=>r.tableId===t.id&&['confirmed','held'].includes(r.status)&&r.start<Date.now()+3600000&&r.end>Date.now());
  return soon?{state:'reserved',text:tr('Reserved','محجوزة')}:{state:'available',text:tr('Available','متاحة')};
 }
 const orders=(data.orders||[]).filter(o=>o.visitId===v.id&&o.status!=='cancelled'),bill=v.bill||{};
 if(orders.some(o=>o.status==='ready'))return {state:'ready',text:tr('Food ready','الطلب جاهز')};
 if(orders.some(o=>['received','preparing'].includes(o.status)))return {state:'preparing',text:tr('In the kitchen','في المطبخ')};
 if(bill.total>0&&bill.due===0)return {state:'paid',text:tr('Paid','مدفوعة')};
 if(v.locked||(data.requests||[]).some(r=>r.visitId===v.id&&r.type==='bill'&&r.status==='open'))return {state:'payment',text:tr('Paying','جارٍ الدفع')};
 if(bill.paid>0)return {state:'partially-paid',text:tr('Part paid','مدفوعة جزئياً')};
 if(!orders.length)return {state:'ordering',text:tr('Seated','جلس الضيوف')};
 return {state:'eating',text:tr('Dining','يتناولون الطعام')};
}
// Kitchen status chain. The server accepts one hop at a time; the board walks
// the chain for you when a card is dragged more than one column ahead.
const TERMINAL=['served','picked_up','delivered'];
const nextStatus=(o,status)=>({received:'preparing',preparing:'ready',ready:o.type==='dine-in'?'served':o.type==='delivery'?'out_for_delivery':'picked_up',out_for_delivery:'delivered'})[status];
const columnOf=status=>TERMINAL.includes(status)?'done':status;
const KITCHEN_COLUMNS=['received','preparing','ready','out_for_delivery','done'];
// Forward-only: the API has no reverse transition, so a backward drop is refused.
function pathTo(orderId,column){
 const o=data.orders.find(x=>x.id===orderId);
 if(!o||columnOf(o.status)===column)return null;
 const steps=[];let status=o.status;
 for(let i=0;i<4;i++){
  const next=nextStatus(o,status);if(!next)return null;
  steps.push(next);status=next;
  if(columnOf(status)===column)return steps;
 }
 return null;
}
async function advanceOrder(id,statuses){
 busy=true;
 try{let o=data.orders.find(x=>x.id===id);
  for(const status of statuses)o=await api('transition',{id,version:o.version,status});
  toast(tr('Order moved to ','تم نقل الطلب إلى ')+kitchenColumnName(columnOf(o.status)));
  await refresh();
 }catch(err){toast(err.message,true);await refresh();}finally{busy=false}
}
const kitchenColumnName=column=>({received:tr('New orders','طلبات جديدة'),preparing:tr('Preparing','تحت التحضير'),ready:tr('Ready to serve','جاهز للتقديم'),out_for_delivery:tr('On the way','في الطريق'),done:tr('Completed','مكتمل')})[column]||column;
let dragging=false;
const OCCUPIED_STATES=['occupied','ordering','eating','preparing','ready','payment','partially-paid','paid'];
