function floor(tables,publicMode=false){return savedFloorSvg(data.floor,tables.filter(t=>t.active).map(t=>{const live=publicMode?{state:t.available?'available':'occupied',text:t.available?tr('Available','متاحة'):tr('Unavailable','غير متاحة')}:tableState(t);return {...t,state:live.state,statusText:live.text,disabled:publicMode&&!t.available}}),selected,'operations')}
