function empty(title,sub){return `<div class="empty"><span>◌</span><h3>${title}</h3><p>${sub}</p></div>`}
function requests(){return data.requests.filter(r=>r.status==='open').map(r=>`<div class="request"><span><strong>${esc(data.tables.find(t=>t.id===r.tableId)?.label||'Offsite')}</strong><small>${r.type==='bill'?'Bill requested':'Waiter requested'} · ${time(r.created)}</small></span>${btn('Resolve','resolve','secondary small',`data-id="${r.id}"`)}</div>`).join('')||'<div class="quiet"><span>✓</span><p>You’re all caught up<small>New guest requests appear here.</small></p></div>'}
// Tables open themselves when a guest scans. Staff get told, and can release
// one for the first minute while it is still empty.
function autoOpenNotice(){
 const fresh=(data.visits||[]).filter(v=>v.status==='open'&&v.auto&&Date.now()-v.created<60000&&!data.orders.some(o=>o.visitId===v.id));
 if(!fresh.length)return '';
 return `<div class="auto-notice">${fresh.map(v=>`<div class="auto-notice-row"><span class="live-dot"></span><div><strong>${esc(data.tables.find(t=>t.id===v.tableId)?.label||'')} · ${tr('opened by a guest scan','فُتحت بمسح الضيف')}</strong><small>${tr('Guests can order now. Release it if this was a mistake.','يقدر الضيوف يطلبوا الآن. حرّرها لو كان بالخطأ.')}</small></div>${btn(tr('Release table','تحرير الطاولة'),'undo-auto','text-button',`data-id="${v.id}"`)}</div>`).join('')}</div>`;
}
function tableDetails(){const t=data.tables.find(t=>t.id===selected);if(!t)return `<section class="panel table-detail"><div class="detail-art">▦</div><h2>A place for every guest</h2><p>Select a table to see its status, seat guests, or open its QR code.</p><div class="detail-tip"><span>↖</span> Your floor, at a glance</div></section>`;const v=data.visits.find(v=>v.tableId===t.id&&v.status==='open'),state=tableStatus(t);return `<section class="panel table-detail"><div class="table-title"><h2>${esc(t.label)}</h2>${badge(state,state)}</div><p>${t.capacity} seats · ${esc(t.zone)}</p>${v?`<hr><h3>${esc(v.name)}</h3><p class="fine">Table open · guests can scan and order.</p><div class="bill-row"><span>Remaining balance</span><strong>EGP ${money(v.bill.due)}</strong></div>${btn('Close visit','close-visit','secondary full',`data-id="${v.id}"`)}`:t.cleaning?btn('✓ Mark as clean','clean','primary full',`data-id="${t.id}"`):btn('＋ Seat guests','seat','primary full',`data-id="${t.id}"`)}<div class="qr-row"><img src="/qr/${t.qr}" alt="QR code for ${esc(t.label)}"><div><strong>Table QR code</strong><p>Scan to see the menu · no PIN</p><a href="/t/${t.qr}" target="_blank">Open guest view ↗</a><a href="/qr/${t.qr}" download="resuto-${esc(t.label)}.svg">Download QR ↓</a></div></div></section>`}
function orderCard(o,controls=false){const next={received:'preparing',preparing:'ready',ready:o.type==='dine-in'?'served':o.type==='delivery'?'out_for_delivery':'picked_up',out_for_delivery:'delivered'}[o.status];return `<article class="order-card" ${controls?`data-order="${o.id}" data-status="${o.status}"`:''}><div class="order-top"><strong>#${String(o.number).padStart(3,'0')}</strong><span>${time(o.created)}</span></div><div class="order-source">${esc(data.tables.find(t=>t.id===o.tableId)?.label||o.type)} <span>· ${esc(o.name)}</span></div>${o.lines.map(l=>`<div class="order-line"><b>${l.qty}</b><div>${esc(language==='ar'?l.nameAr||l.name:l.name)}<small>${esc(l.station)}</small></div></div>`).join('')}${o.notes?`<p class="order-note">${esc(o.notes)}</p>`:''}${controls?btn(({preparing:'Start preparing',ready:'Mark ready',served:'Mark served',picked_up:'Mark picked up',out_for_delivery:'Send for delivery',delivered:'Mark delivered'})[next],'transition','primary full',`data-id="${o.id}" data-status="${next}"`)+(role==='manager'&&o.status==='received'?btn('Cancel order','cancel-order','text-button full',`data-id="${o.id}"`):''):badge(o.status,o.status)}</article>`}
function guestShell(content){$('#app').innerHTML=`<div class="guest-app"><header class="guest-header"><a href="/restaurant" class="restaurant-brand">${esc(data.settings.name)}<small>AT OUR TABLE</small></a><nav><a href="/reserve">Reserve a table</a><a href="/menu">Order ahead</a><a class="powered-link" href="/">Powered by Resuto ↗</a></nav></header>${content}<footer><span>${esc(data.settings.name)} · ${esc(data.settings.branch)}</span><span>Example restaurant · Test payments</span><a href="/">Powered by Resuto</a></footer></div>`}
function renderGuest(){if(path==='/'){document.title='Resuto · Restaurant operations, brought together';$('#app').innerHTML=saasPage();return}if(path==='/restaurant'){document.title=data.settings.name+' · A place at our table';guestShell(restaurantPage(data));return}

 if(path==='/reserve'){guestShell(`<main class="guest-page"><div class="eyebrow">COME ON IN</div><h1>Your evening starts here.</h1><p class="intro">Choose a time, find your table, and make it yours.</p><div class="reservation-layout"><section class="panel"><div class="panel-head"><h2>Pick your favorite spot</h2><div class="legend"><span><i class="dot available"></i>Available</span><span><i class="dot occupied"></i>Unavailable</span></div></div>${floor(data.tables,true)}</section><section class="panel padded"><form data-form="reserve">${field('Your name','name','text','','required autocomplete="name"')}${field('Phone or email','contact','text','','required')}<div class="form-grid">${field('Date & time (Cairo)','start','datetime-local',cairoInput(),'required')}${field('Guests','party','number',2,'min="1" max="20" required')}</div>${btn('Check availability','availability','secondary full')}<label>Selected table<select name="tableId" required><option value="">Choose on the map or here</option>${data.tables.filter(t=>t.available).map(t=>`<option value="${t.id}" ${selected===t.id?'selected':''}>${esc(t.label)} · ${t.capacity} seats · ${esc(t.zone)}</option>`).join('')}</select></label><div class="deposit-note"><strong>EGP ${money(data.settings.deposit)} test deposit</strong><p>Your table is held for 5 minutes. The deposit is credited to your bill at check-in.</p></div><button class="primary full">Hold this table →</button><p class="fine">${data.settings.duration}-minute reservation. No real money is charged.</p></form></section></div></main>`);return}
 if(path==='/menu'&&!visit){guestShell(`<main class="guest-page narrow"><div class="eyebrow">FRESH FROM OUR KITCHEN</div><h1>Good food, your way.</h1><p class="intro">Start an order for pickup${data.settings.deliveryEnabled?' or delivery':''}.</p><section class="panel padded"><form data-form="offsite"><label>Order type<select name="type"><option value="pickup">Pickup</option>${data.settings.deliveryEnabled?`<option value="delivery">Delivery · EGP ${money(data.settings.deliveryFee)}</option>`:''}</select></label>${field('Your name','name','text','','required')}${field('Phone number','contact','tel','','required')}${field('Delivery address (required for delivery)','address')}${field('Requested time / pickup note','requested','text','','placeholder="For example, around 7 pm"')}<button class="primary full">Explore the menu →</button></form></section></main>`);return}
 if(!visit){guestShell(`<main class="guest-page narrow"><div class="eyebrow">WELCOME TO YOUR TABLE</div><h1>Let’s get you seated.</h1><p class="intro">Scan the QR on your table to browse and order, or start a pickup order.</p><a class="primary button" href="/menu">Order for pickup or delivery →</a></main>`);return}
 guestShell(`<main class="guest-page menu-page"><div class="menu-heading"><div><div class="eyebrow">${esc(data.settings.name)} · ${esc(visit.type)}</div><h1>A little of what you love.</h1><p class="intro">${esc(visit.name)}${visit.status==='closed'?' · Your visit is complete. Thank you!':visit.locked?' · Your bill is being settled.':' · Made fresh, ordered at your pace.'}</p></div><div>${visit.type==='dine-in'&&visit.status==='open'?btn('Call waiter','waiter','secondary'):''} ${visit.status!=='preview'?btn('View bill','bill','primary'):''}</div></div><div class="ordering-layout"><section><div class="assistant-banner"><span class="spark">✧</span><div><strong>Something you’ll love, within your budget.</strong><p>Let the menu assistant help you choose.</p></div>${btn('Help me choose ↗','assistant','secondary')}</div><div class="categories">${['All items',...new Set(data.menu.map(m=>m.category))].map(c=>btn(esc(c),'category',category===c?'category active':'category',`data-id="${esc(c)}"`)).join('')}</div><div class="menu-grid">${data.menu.filter(m=>category==='All items'||m.category===category).map(m=>`<article class="menu-card"><div class="menu-category">${esc(m.category)} <span>${m.vegetarian?'◉ Vegetarian':''}</span></div><h3>${esc(localizedName(m))}</h3><p>${m.allergens.length?'Contains '+esc(m.allergens.join(', ')):'No listed allergens. Check with staff.'}</p><div><strong>EGP ${money(m.price)}</strong>${btn(m.stock&&m.available?'＋':'Sold out','add','add-button',`data-id="${m.id}" ${!m.stock||!m.available||visit.locked||visit.status==='closed'?'disabled':''}`)}</div></article>`).join('')}</div>${visit.orders.length?`<h2 class="section-title">From our kitchen</h2><div class="cards">${visit.orders.map(o=>orderCard(o)).join('')}</div>`:''}</section><aside><section class="panel padded cart-panel"><div class="panel-head"><h2>Your order</h2>${badge(String(Object.values(cart).reduce((n,l)=>n+l.qty,0)))}</div>${Object.entries(cart).map(([id,l])=>`<div class="cart-line"><div><strong>${esc(data.menu.find(m=>m.id===id)?.name)}</strong><small>EGP ${money(l.price*l.qty)}</small></div><div class="stepper">${btn('−','minus','icon',`data-id="${id}"`)}<span>${l.qty}</span>${btn('+','add','icon',`data-id="${id}"`)}</div></div>`).join('')||'<p class="cart-empty">A good meal starts with a choice.<br>Add something from the menu.</p>'}<label>Notes for the kitchen<textarea id="notes" placeholder="Any special requests?">${esc(sessionStorage.getItem('resuto-notes')||'')}</textarea></label><div class="bill-row total"><span>Subtotal</span><strong>EGP ${money(Object.values(cart).reduce((n,l)=>n+l.price*l.qty,0))}</strong></div>${btn('Confirm order →','submit-order','primary full',`${!Object.keys(cart).length||visit.locked||visit.status!=='open'?'disabled':''}`)}<p class="fine">Orders are sent only when you confirm.</p></section></aside></div></main>`)
}
function cairoInput(){const p=new Intl.DateTimeFormat('sv-SE',{timeZone:'Africa/Cairo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(Date.now()+3600000));return p.replace(' ','T')}
function cairoDate(value){let guess=Date.parse(value+'Z');for(let i=0;i<3;i++){const local=new Intl.DateTimeFormat('sv-SE',{timeZone:'Africa/Cairo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date(guess)).replace(' ','T');guess+=Date.parse(value+'Z')-Date.parse(local+'Z')}return guess}
function formKey(form,payload){const fingerprint=JSON.stringify(payload);if(form.dataset.fingerprint!==fingerprint){form.dataset.fingerprint=fingerprint;form.dataset.key=key()}return form.dataset.key}
async function optimizeMenuImage(file,{zoom=1,focus=50}={}){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8_000_000)throw Error('Choose a PNG, JPEG or WebP image under 8 MB.');const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas');canvas.width=1200;canvas.height=900;const context=canvas.getContext('2d'),scale=Math.max(canvas.width/bitmap.width,canvas.height/bitmap.height)*Number(zoom),width=bitmap.width*scale,height=bitmap.height*scale,x=(canvas.width-width)*Number(focus)/100,y=(canvas.height-height)/2;context.drawImage(bitmap,x,y,width,height);bitmap.close();const data=canvas.toDataURL('image/webp',.82).split(',')[1];if(data.length*3/4>800000)throw Error('The optimized image is still too large. Choose a smaller source.');return {mime:'image/webp',data};}
function saveCart(){sessionStorage.setItem('resuto-cart',JSON.stringify(cart))}
async function refresh(render=true){try{if(staff){const previous=data?.revision;data=await api('staff');if(data.role!==role)throw Object.assign(new Error('Please sign in to this workspace.'),{status:401});
 // Re-render only when the server state actually moved on. Repainting every
 // poll reset scroll position and made the floor plan flicker.
 if(render&&previous!==undefined&&previous===data.revision)render=false;
 if(render){if(path==='/manager/setup'){editing=true;await mountSetup($('#app'))}else if(path==='/manager/floor-editor'){editing=true;await mountFloorEditor($('#app'),api,toast)}else renderStaff()}}else{data=await api('public');if(path.startsWith('/t/')){const joined=await api('table-session',{qr:path.split('/')[2]});token=joined.token;if(token)sessionStorage.setItem('resuto-token',token);else{sessionStorage.removeItem('resuto-token');visit={name:joined.label+' · Browse the menu; ask staff to open your table to order',type:'dine-in',status:'preview',orders:[],bill:{due:0}};}}if(token&&path==='/order'||token&&path.startsWith('/t/')){try{const v=await api('visit');if(!path.startsWith('/t/')||(v.status==='open'&&data.tables.find(t=>t.qr===path.split('/')[2])?.id===v.tableId))visit=v;else visit=null}catch{visit=null}}if(render)renderGuest()}lastError=false}catch(e){if(staff&&e.status===401){data=null;firebaseContextReady=false;renderLogin()}else{lastError=true;if($('.sync-status'))$('.sync-status').textContent='Connection lost · retrying';if(!data)$('#app').innerHTML=`<div class="empty"><h1>We couldn’t connect</h1><p>${esc(e.message)}</p>${btn('Try again','retry')}</div>`;else toast(e.message,true)}}}
function renderLogin(){
 const roleLinks=[['manager','Manager','/manager'],['kitchen','Kitchen','/kitchen'],['host','Front desk','/host']].filter(([id])=>id!==role).map(([,label,href])=>`<a href="${href}">${label} workspace ↗</a>`).join('');
 $('#app').innerHTML=`<div class="login"><div class="login-brand"><a href="/" class="brand"><span class="brand-mark">r</span>resuto.</a><div><div class="eyebrow">A CALMER KIND OF SERVICE</div><h1>Every table.<br>Every order.<br>All together.</h1><p>Your restaurant, in good hands.</p></div><small>RESTAURANT OPERATING WORKSPACE</small></div><main><div><form data-form="login"><div class="eyebrow">${role.toUpperCase()} WORKSPACE</div><h1>Welcome back.</h1><p>Sign in to your restaurant account.</p>${field('Email','email','email','','required autocomplete="email"')}${field('Password','password','password','','required autocomplete="current-password"')}<button class="primary full">Sign in →</button><button type="button" class="secondary full" data-action="google-login">Continue with Google</button><p class="fine">Your account determines which restaurant and data you can access.</p><a href="/account">Create a restaurant account or reset password ↗</a><div class="role-links">${roleLinks}</div></form><details><summary>Olive Room demo access</summary><form data-form="login-demo">${field('Demo password','password','password','','required')}<button class="secondary full">Open demo</button></form></details></div></main></div>`;
}
document.addEventListener('change',e=>{if(e.target.name==='serviceMode'){data.settings.serviceMode=e.target.value;renderStaff();return}if(e.target.name==='provider'){const details=$('#paymob-details');if(details){details.hidden=e.target.value!=='paymob';details.querySelectorAll('input').forEach(i=>i.required=!details.hidden)}}});
document.addEventListener('input',e=>{if(['split-mode','split-people','split-cover'].includes(e.target.id)){const mode=$('#split-mode').value,people=Math.max(1,Math.min(50,Number($('#split-people').value)||1)),cover=mode==='share'?1:Math.max(1,Math.min(people,Number($('#split-cover').value)||1));if(mode!=='custom')$('[name="amount"]').value=(mode==='full'?visit.bill.due:Math.floor(visit.bill.due/people)*cover+Math.min(visit.bill.due%people,cover))/100;}
if(e.target.id==='notes')sessionStorage.setItem('resuto-notes',e.target.value)});
document.addEventListener('keydown',e=>{if(!['Enter',' '].includes(e.key))return;const table=e.target.closest('[data-action="select-table"]');if(table){e.preventDefault();table.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,id=el.dataset.id;try{
 if(a==='dismiss'){close();return}if(a==='retry')return refresh();if(a==='google-login'){await googleSignIn();firebaseContextReady=false;await firebaseIdToken(true);await refresh();return}if(a==='tab'){tab=id;selected=null;renderStaff();return}
 if(a==='select-table'){if(el.getAttribute?.('aria-disabled')==='true')return;selected=id;if(staff){tab='floor';renderStaff()}else if(path==='/reserve'){$('[name="tableId"]').value=id;document.querySelectorAll('[data-action="select-table"]').forEach(x=>x.classList.toggle('is-selected',x.dataset.id===id))}else location.href='/reserve';return}
 if(a==='category'){category=id;renderGuest();return}if(a==='add'||a==='minus'){const m=data.menu.find(m=>m.id===id);if(a==='add'){if((cart[id]?.qty||0)>=m.stock)throw Error('No more portions available.');cart[id]={qty:(cart[id]?.qty||0)+1,price:m.price}}else if(--cart[id].qty<=0)delete cart[id];saveCart();renderGuest();return}
 if(a==='logout'){await Promise.allSettled([api('logout',{}),firebaseSignOut()]);firebaseContextReady=false;return renderLogin()}
 if(a==='walkin'||a==='seat'){const open=data.tables.filter(t=>t.active&&tableStatus(t)==='available').sort((x,y)=>x.capacity-y.capacity);
  if(!open.length){toast(tr('Every table is in service right now.','كل الطاولات في الخدمة حالياً.'),true);return}
  modal(tr('Seat a walk-in','استقبال ضيف'),`<form data-form="seat">${field(tr('Guest name','اسم الضيف'),'name','text','Walk-in','required')}<label>${tr('Table','الطاولة')}<select name="tableId">${open.map(t=>`<option value="${t.id}" ${t.id===id?'selected':''}>${esc(t.label)} · ${t.capacity} ${tr('seats','مقاعد')} · ${esc(t.zone||'')}</option>`).join('')}</select></label><button class="primary full">${tr('Start visit','بدء الزيارة')}</button></form>`);return}
 if(a==='undo-auto'){await api('undo-auto-open',{id});toast(tr('Table released.','تم تحرير الطاولة.'))}
 if(a==='clean'){await api('clean',{id});toast('Table ready for guests.')}if(a==='checkin'){const r=data.reservations.find(r=>r.id===id);const v=await api('seat',{tableId:r.tableId,reservationId:id});toast('Checked in. Guests can scan the table QR to order.')}
 if(a==='cancel-reservation'){modal('Cancel this reservation?',`<p>The table will be released and the guest's hold or booking will be cancelled.</p>${btn('Cancel reservation','confirm-cancel-reservation','primary full',`data-id="${id}"`)}`);return}
 if(a==='confirm-cancel-reservation'){await api('reservation-cancel',{id});close();toast('Reservation cancelled.')}
 if(a==='close-visit'){modal('Close this visit?',`<p>All orders must be fulfilled and the balance settled. The table will then need cleaning. Any unused deposit credit gets a test refund.</p>${btn('Close visit','confirm-close','primary full',`data-id="${id}"`)}`);return}
 if(a==='confirm-close'){const r=await api('close',{id});close();toast('Visit closed.'+(r.refund?' Test refund: EGP '+money(r.refund):''))}
 if(a==='resolve')await api('resolve',{id});if(a==='transition'){const o=data.orders.find(o=>o.id===id);await api('transition',{id,version:o.version,status:el.dataset.status});toast('Order updated.')}
 if(a==='cancel-order'){modal('Cancel this order?',`<p>Only an unstarted order can be cancelled. Its portions will return to inventory.</p>${btn('Cancel order','confirm-cancel','primary full',`data-id="${id}"`)}`);return}
 if(a==='confirm-cancel'){const o=data.orders.find(o=>o.id===id);await api('transition',{id,version:o.version,status:'cancelled'});close();toast('Order cancelled. Portions restored.')}
 if(a==='media-edit'){editing=true;await openMenuImage(data.menu.find(x=>x.id===id),api,()=>{editing=false;refresh();});return}
 if(a==='media-save'){const file=$('#menu-media-file')?.files[0];if(!file)throw Error('Choose an image first.');el.disabled=true;const encoded=await optimizeMenuImage(file,{zoom:$('#menu-media-zoom').value,focus:$('#menu-media-focus').value});await api('menu-image',{menuItemId:id,...encoded});close();toast('Menu image saved.');await refresh();return}
 if(a==='media-remove'){el.disabled=true;await api('menu-image',{menuItemId:id,action:'remove'});close();toast('Menu image removed.');await refresh();return}
 if(a==='edit-menu'||a==='add-menu'){const m=data.menu.find(m=>m.id===id)||{id:'',name:'',category:'Mains',station:'Hot kitchen',price:10000,stock:10,available:true,allergens:[],vegetarian:false,version:0};modal(m.id?esc(localizedName(m)):'Add a menu item',`<form data-form="menu" data-id="${m.id}" data-version="${m.version}">${field('Item name','name','text',m.name,'required maxlength="100"')}<div class="form-grid">${field('Category','category','text',m.category,'required maxlength="40"')}${field('Kitchen station','station','text',m.station,'required maxlength="40"')}${field('Price (EGP)','price','number',m.price/100,'min="0.01" step="0.01" required')}${field('Available portions','stock','number',m.stock,'min="0" required')}</div>${field('Listed allergens (comma separated)','allergens','text',m.allergens.join(', '))}<label class="check"><input type="checkbox" name="vegetarian" ${m.vegetarian?'checked':''}> Vegetarian</label><label class="check"><input type="checkbox" name="available" ${m.available?'checked':''}> Available to order</label><p class="fine">Uncheck availability to retire an item while preserving order history.</p><button class="primary full">Save menu item</button></form>`);return}
 if(a==='layout'){location.href='/manager/floor-editor';return}
 if(a==='remove-background'){await api('background',{image:null});close();toast('Floor background removed.')}
 if(a==='add-table'){await api('table',{add:true});close();toast('Table added. Select Edit layout to position it.')}
 if(a==='edit-table'){const t=data.tables.find(t=>t.id===id);close();modal('Edit '+esc(t.label),`<form data-form="table" data-id="${t.id}" data-version="${t.version}"><div class="form-grid">${field('Table label','label','text',t.label,'required')}${field('Zone','zone','text',t.zone,'required')}${field('Seats','capacity','number',t.capacity,'min="1" max="20" required')}<label>Shape<select name="shape"><option value="square" ${t.shape==='square'?'selected':''}>Square</option><option value="round" ${t.shape==='round'?'selected':''}>Round</option></select></label>${field('Horizontal position (%)','x','number',t.x,'min="8" max="92" required')}${field('Vertical position (%)','y','number',t.y,'min="15" max="85" required')}</div><label class="check"><input type="checkbox" name="active" checked> Active table</label><p class="fine">Uncheck to archive. Tables with an open visit or future booking cannot be archived.</p><button class="primary full">Save layout</button></form>`);return}
 if(a==='print'){modal('Table QR print sheet',`<div class="print-grid">${data.tables.filter(t=>t.active).map(t=>`<div><img src="/qr/${t.qr}" alt="${esc(t.label)} QR"><h3>${esc(t.label)}</h3><p>Scan to browse, order & split the bill</p></div>`).join('')}</div>${btn('Print QR codes','do-print','primary full')}`);return}if(a==='do-print'){window.print();return}
 if(a==='availability'){const f=$('form'),fd=new FormData(f);data=await api('public?start='+cairoDate(fd.get('start')));const vals=Object.fromEntries(fd);renderGuest();for(const [k,v]of Object.entries(vals))if($(`[name="${k}"]`))$(`[name="${k}"]`).value=v;toast('Availability updated for your selected time.');return}
 if(a==='submit-order'){if(busy)return;busy=true;el.disabled=true;const payload={lines:Object.entries(cart).map(([id,l])=>({id,...l})),notes:$('#notes').value};let pending=JSON.parse(sessionStorage.getItem('pending-order')||'null');if(!pending||JSON.stringify(pending.payload)!==JSON.stringify(payload))pending={key:key(),payload};sessionStorage.setItem('pending-order',JSON.stringify(pending));await api('order',{...payload,key:pending.key});sessionStorage.removeItem('pending-order');cart={};saveCart();sessionStorage.removeItem('resuto-notes');toast('Order sent to the kitchen.')}
 if(a==='waiter'){await api('request',{type:'waiter',key:key()});toast('Your server has been notified.')}
 if(a==='bill'){visit=await api('visit');modal('Split & pay',`<div class="bill-row"><span>Food & drinks</span><strong>EGP ${money(visit.bill.subtotal)}</strong></div><div class="bill-row"><span>Delivery fee</span><strong>EGP ${money(visit.bill.fee)}</strong></div><div class="bill-row"><span>Reservation credit</span><strong>− EGP ${money(visit.bill.credit)}</strong></div><div class="bill-row"><span>Payments made</span><strong>− EGP ${money(visit.bill.paid)}</strong></div><div class="bill-row total"><span>Remaining</span><strong>EGP ${money(visit.bill.due)}</strong></div>${visit.bill.due?`<form data-form="pay"><label>How would you like to split?<select id="split-mode"><option value="full">Pay the full remaining bill</option><option value="share">Pay my equal share</option><option value="family">Pay for my family / group</option><option value="custom">Choose an amount</option></select></label><div class="form-grid"><label>People sharing the remaining bill<input id="split-people" type="number" min="1" max="50" value="2"></label><label>People I am paying for<input id="split-cover" type="number" min="1" max="50" value="1"></label></div><p class="fine">Equal shares divide the remaining balance. Extra cents go to the first shares.</p>${field('Amount to pay (EGP)','amount','number',visit.bill.due/100,`min="0.01" max="${visit.bill.due/100}" step="0.01" required`)}<label>Payment method<select name="provider">${data.payments?.mode!=='live'?'<option value="test">Simulated payment · no charge</option>':''}${(data.payments?.providers||[]).map(p=>'<option value="'+p+'">'+(p==='paymob'?'Paymob':'Stripe')+' secure checkout</option>').join('')}</select></label><div id="paymob-details" hidden>${field('First name','firstName')}${field('Last name','lastName')}${field('Email','email','email')}${field('Phone','phone','tel')}</div><p class="fine">Starting checkout pauses new orders. Online payments are confirmed by the provider. Returning here alone does not confirm payment.</p><button class="primary full">Continue with payment</button></form>`:'<p class="success-note">Your current balance is settled.</p>'}${(visit.checkout||[]).map(c=>c.url?`<p><a class="primary button" href="${esc(c.url)}">Resume ${esc(c.provider)} checkout · EGP ${money(c.amount)}</a></p>`:'<p>Checkout pending. Ask staff to reconcile it before paying again.</p>').join('')}${visit.status==='open'?btn('Request bill from staff','request-bill','secondary full'):''}`);$('[name="provider"]')?.dispatchEvent(new Event('change',{bubbles:true}));return}
 if(a==='request-bill'){await api('request',{type:'bill',key:key()});close();toast('Bill requested. Ordering is now paused.')}
 if(a==='assistant'){modal('Find your next favorite',`<form data-form="assistant">${field('What are you in the mood for?','text','text','','placeholder="A light vegetarian dinner for two"')}<div class="form-grid">${field('Total budget (EGP)','budget','number',400,'min="1" required')}${field('People','party','number',2,'min="1" max="20" required')}</div><label class="check"><input name="vegetarian" type="checkbox"> Vegetarian only</label><label>Exclude listed allergens<select name="exclude"><option value="">None</option>${['milk','eggs','wheat','fish'].map(x=>`<option>${x}</option>`).join('')}</select></label><button class="primary full">Suggest a meal ✧</button></form><div id="suggestion"></div>`);return}
 if(a==='accept-suggestion'){for(const l of window.suggestion.lines){const m=data.menu.find(m=>m.id===l.id);cart[l.id]={qty:(cart[l.id]?.qty||0)+l.qty,price:m.price}}saveCart();close();toast('Suggestion added. Review your cart and confirm your order.')}
 if(a==='deposit'){const r=await api('deposit',{token:el.dataset.token,key:el.dataset.key});close();modal('Your table is confirmed',`<div class="confirmation">✓</div><h3>We’ll see you at ${time(r.start)}.</h3><p>${esc(r.name)} · ${r.party} guests</p><p>EGP ${money(r.deposit)} test deposit confirmed. Staff will check you in on arrival then scan your table QR to order.</p>${btn('Done','dismiss','primary full')}`);return}
 await refresh();
 }catch(err){if(a==='submit-order'&&err.message.includes('price changed')){data=await api('public');for(const [id,l]of Object.entries(cart)){const m=data.menu.find(m=>m.id===id);if(m)l.price=m.price;}saveCart();renderGuest();}toast(err.message,true);el.disabled=false}finally{busy=false}});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.dataset.form)return;e.preventDefault();if(busy)return;busy=true;const submit=f.querySelector('button[type="submit"],button:not([type])');if(submit)submit.disabled=true;const b=Object.fromEntries(new FormData(f)),type=f.dataset.form;try{
 if(type==='login'){await emailSignIn(b.email,b.password);firebaseContextReady=false;await refresh();return}
 if(type==='login-demo'){await api('login',{role,password:b.password});await refresh();return}
 if(type==='seat'){const v=await api('seat',b);close();selected=v.tableId;toast('Visit started. Guests can scan the table QR to order.')}
 if(type==='settings'){for(const n of ['duration','buffer'])b[n]=Number(b[n]);for(const n of ['deposit','deliveryFee'])b[n]=Math.round(Number(b[n])*100);b.deliveryEnabled=!!b.deliveryEnabled;b.reservationsEnabled=!!b.reservationsEnabled;await api('settings',b);toast('Settings saved.');await refresh()}
 if(type==='menu'){await api('menu',{...b,id:f.dataset.id,add:!f.dataset.id,version:Number(f.dataset.version),price:Math.round(Number(b.price)*100),stock:Number(b.stock),available:!!b.available,vegetarian:!!b.vegetarian,allergens:b.allergens.split(',').map(x=>x.trim().toLowerCase()).filter(Boolean)});close();toast('Menu item saved.')}
 if(type==='table'){await api('table',{...b,id:f.dataset.id,version:Number(f.dataset.version),capacity:Number(b.capacity),x:Number(b.x),y:Number(b.y),active:!!b.active});close();toast('Floor layout saved. QR identity preserved.')}
 if(type==='reserve'){const payload={...b,start:cairoDate(b.start),party:Number(b.party)};const r=await api('reserve',{...payload,key:formKey(f,b)});modal('Your table is held',`<div class="confirmation">◷</div><h3>One more step, ${esc(r.name)}.</h3><p>Confirm your EGP ${money(r.deposit)} test deposit before ${time(r.expires)} to secure your table.</p><p class="fine">This is a payment simulation. No card details or real money are involved.</p>${btn('Confirm test deposit','deposit','primary full',`data-token="${r.token}" data-key="${key()}"`)}`);return}
 if(type==='offsite'){const v=await api('offsite',{...b,key:formKey(f,b)});token=v.token;sessionStorage.setItem('resuto-token',token);location.href='/order';return}
 if(type==='join'){const v=await api('join',{qr:path.split('/')[2],pin:b.pin});token=v.token;sessionStorage.setItem('resuto-token',token)}
 if(type==='pay'&&b.provider!=='test'){const r=await api('checkout',{...b,amount:Math.round(Number(b.amount)*100),key:formKey(f,b)});location.href=r.url;return}
 if(type==='pay'){await api('pay',{amount:Math.round(Number(b.amount)*100),key:formKey(f,b)});close();toast('Test payment recorded. Shared balance updated.')}
 if(type==='assistant'){const r=await api('recommend',{...b,budget:Math.round(Number(b.budget)*100),party:Number(b.party),vegetarian:!!b.vegetarian,exclude:b.exclude?[b.exclude]:[]});window.suggestion=r;$('#suggestion').innerHTML=`<div class="suggestion">${badge(r.mode)}<p>${esc(r.explanation)}</p>${r.lines.map(l=>`<p><strong>${l.qty} × ${esc(data.menu.find(m=>m.id===l.id)?.name)}</strong></p>`).join('')}<p class="fine">${esc(r.allergyNote)}</p>${r.lines.length?btn('Add suggestion to cart','accept-suggestion','primary full'):''}</div>`;return}
 await refresh();
 }catch(err){toast(err.message,true)}finally{busy=false;if(submit)submit.disabled=false}});
await refresh();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'read_current_menu',title:'Read current menu',description:'Read current restaurant menu prices, listed allergens and portions. Does not order.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async()=>{const current=await api('public');return {currency:'EGP',pricesInMinorUnits:true,menu:current.menu}}},{signal:lifecycle.signal})).catch(()=>{})}catch{}}
setInterval(async()=>{if((tab==='data'||tab==='integrations'||tab==='inventory')&&staff)return;if(visit?.status==='preview'&&!document.hidden&&!editing&&!busy){await refresh();return;}if(path==='/manager/floor-editor'||document.hidden||busy||editing||dragging)return;
 // Typing must not freeze the floor. Keep polling; just hold the repaint back
 // until the field is released, so the manager never loses what they typed.
 if(staff&&data)await refresh(!document.activeElement?.matches('input,textarea,select'));else if(visit){try{const v=await api('visit');if(JSON.stringify(v)!==JSON.stringify(visit)){visit=v;renderGuest()}}catch(e){toast('Connection lost. Retrying…',true)}}},2000);

window.addEventListener('hashchange',()=>{if(['menu','data','integrations','floor','branches'].includes((location.hash||'').slice(1))){tab=(location.hash||'').slice(1);renderStaff();}});
